/* eslint-disable @typescript-eslint/no-unused-vars -- port of the team's closure: dead locals and shapes stay as delivered */
// Literal port of the team's Casa3DSDK (module interaction/items). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installInteractionItems(K: Kernel, shared: Shared): void {
  const { t, LIGHTS, cursor, definePiece, localOf, registerCollision, togglePiece } = K;
  // ---------- construction of the items (called by houseItems) ----------
  const DOOR_ITEM = /^(tv_unit|tv_unit_small|tv_unit_large|sideboard|china_cabinet|filing_cabinet|pantry|laundry_cabinet|wardrobe|wardrobe_small|wardrobe_large|closet_wardrobe|kitchen_cabinet|kitchen_cabinet_large|kitchen_cabinet_small|fridge|fridge_large|display_fridge_medium|display_fridge)$/;
  const DRAWER_ITEM = /^(console_table|dresser|nightstand|vanity_table)$/;
  const LIGHT_TYPES = new Set(['ceiling_light', 'pendant', 'chandelier', 'track_spot', 'hanging_plant']);
  function objectName(type, drawer) { return drawer ? 'drawer' : /^wardrobe/.test(type) ? 'wardrobe' : /fridge|refrig|freezer/.test(type) ? 'fridge' : /pantry/.test(type) ? 'pantry' : 'cabinet'; }
  function recordApi(api) { const calls = [], pr = { light: (MM, ...a) => api.light(MM, ...a) }; for (const n of ['box', 'cylinder', 'leaf', 'plane']) pr[n] = (MM, ...a) => { calls.push([n, a]); }; return { pr, calls }; }
  function buildItem(m, M, ent, api, parent) {
    registerCollision(m, M);
    const type = m.type;
    if (LIGHT_TYPES.has(type)) return lightItem(m, M, ent, api, parent);
    if (type === 'curtain') return curtainItem(m, M, ent, api, parent);
    if (DOOR_ITEM.test(type) || DRAWER_ITEM.test(type)) return furnitureItem(m, M, ent, api, parent, DRAWER_ITEM.test(type));
    ent.f(M, api);
  }
  function lightItem(m, M, ent, api, parent) { // own lamp: separate mesh and lights tagged with the room
    M.on = M.light = M.lit = true; const n0 = LIGHTS.length, name = shared.quality === 'game' ? 'ix:light:' + m.room + '@' + parent : 'ix:light:' + m.id; // 'game': all the room's lamps in a single piece
    cursor.group = name; try { ent.f(M, api); } finally { cursor.group = parent; }
    for (let i = n0; i < LIGHTS.length; i++) LIGHTS[i].roomId = m.room;
    if (!shared.inter.defs.has(name)) definePiece(name, { kind: 'light', pivot: [0, 0, 0], ry: 0, parent, roomId: m.room }); shared.inter.litRooms.add(m.room);
  }
  function curtainItem(m, M, ent, api, parent) {
    M.open = false; const { pr, calls } = recordApi(api); ent.f(M, pr);
    const side = { '-1': [], '1': [] }; const body = [];
    for (const c of calls) { const a = c[1]; if (c[0] === 'box' && a[0] === 'fabric') side[a[1] < 0 ? '-1' : '1'].push(c); else body.push(c); }
    const opens = Math.min(0.5, (M.w || 1.6) * 0.3), open0 = !!m.doorOpen, parts = [];
    for (const sd of [-1, 1]) {
      const L = side[sd]; if (!L.length) continue;
      const exterior = Math.max(...L.map(c => Math.abs(c[1][1]) + c[1][4] / 2)), inn = Math.min(...L.map(c => Math.abs(c[1][1]) - c[1][4] / 2)), width = Math.max(0.2, exterior - Math.max(0, inn));
      const [px, pz] = localOf(M, sd * exterior, 0), name = 'ix:curtain:' + m.id + ':' + (sd < 0 ? 'E' : 'D');
      const p = definePiece(name, { kind: 'curtain', pivot: [px, M.base, pz], ry: M.ry, parent, k: Math.max(0.15, Math.min(1, opens / width)), t0: open0 ? 1 : 0 }); parts.push(p);
      cursor.group = name; for (const c of L) api[c[0]](M, ...c[1]); cursor.group = parent;
    }
    for (const c of body) api[c[0]](M, ...c[1]);
    if (!parts.length) return;
    const [ax, az] = localOf(M, 0, 0.2);
    shared.inter.items.push({ type: 'curtain', id: m.id, floor: M.floor, anchor: [ax, M.base + (M.y || 0) + (m.h || 2) * 0.5, az], range: 2.4, angle: 1.0, pieces: parts, text: () => t(parts[0].target > 0.5 ? 'prompt.close' : 'prompt.open', { what: t('what.curtain') }), action: () => { const al = parts[0].target > 0.5 ? 0 : 1; for (const p of parts) { p.target = al; shared.partState.set(p.name, al); shared.inter.anim.add(p); } } });
  }
  function furnitureItem(m, M, ent, api, parent, drawer) {
    const { pr, calls } = recordApi(api), front = M.d / 2; ent.f(M, pr);
    const panels = []; // {i, x0,x1,y0,y1, zc, ext:[indices], h: pull side}
    calls.forEach((c, i) => {
      if (c[0] !== 'box') return; const [mat, x, y, z, w, h, d, , ry, rx, rz] = c[1];
      if (ry || rx || rz) return;
      const ok = drawer ? (mat === 'wood' && d <= 0.02 && z + d / 2 >= front - 0.005 && h >= 0.08 && w >= 0.15)
        : ((mat === 'plain' || mat === 'wood') && d <= 0.045 && z + d / 2 >= front - 0.03 && h >= 0.25 && w >= 0.2 && w <= M.w * 1.02);
      if (ok) panels.push({ i, x0: x - w / 2, x1: x + w / 2, y0: y, y1: y + h, zc: z, exterior: [], grip: 0 });
    });
    const owner = new Map(); // call index -> panel
    panels.forEach(p => owner.set(p.i, p));
    const overlap = (a0, a1, b0, b1) => Math.min(a1, b1) - Math.max(a0, b0);
    calls.forEach((c, i) => {
      if (owner.has(i)) return; const a = c[1]; let x0, x1, y0, y1, ok = false, grip = 0, wide = false;
      if (c[0] === 'box') { const [mat, x, y, z, w, h, d, , ry, rx, rz] = a; if (ry || rx || rz || d > 0.05 || z + d / 2 < front - 0.005 || w > M.w * 1.01) return; if (!(mat === 'metal' || mat === 'glass' || mat === 'plain')) return; x0 = x - w / 2; x1 = x + w / 2; y0 = y; y1 = y + h; ok = true; grip = mat === 'metal' && w <= 0.06 ? x : 0; wide = mat === 'glass'; }
      else if (c[0] === 'cylinder') { const [mat, x, y, z, r] = a; if (mat !== 'metal' || z < front - 0.005 || r > 0.03) return; x0 = x - r; x1 = x + r; y0 = y - r; y1 = y + r; ok = true; }
      if (!ok) return;
      const candidate = panels.filter(p => overlap(x0, x1, p.x0, p.x1) > 0 && overlap(y0, y1, p.y0, p.y1) > 0);
      if (!candidate.length) return;
      if (wide && candidate.length > 1) { for (const p of candidate) { p.exterior.push(['box', [a[0], (p.x0 + p.x1) / 2, a[2], a[3], p.x1 - p.x0 - 0.02, a[5], a[6], a[7], a[8], a[9], a[10]]]); } owner.set(i, 'dup'); return; }
      candidate.sort((p, q) => overlap(x0, x1, q.x0, q.x1) - overlap(x0, x1, p.x0, p.x1));
      owner.set(i, candidate[0]); if (grip) candidate[0].grip = grip;
    });
    const name = objectName(m.type, drawer), parts = [];
    panels.forEach((p, k) => {
      const nm = 'ix:' + (drawer ? 'drawer' : 'door') + ':' + m.id + ':' + k, cx = (p.x0 + p.x1) / 2, width = p.x1 - p.x0;
      let def;
      if (drawer) { const [px, pz] = localOf(M, cx, front); def = definePiece(nm, { kind: 'drawer', pivot: [px, M.base, pz], ry: M.ry, parent, travel: Math.min(0.34, M.d * 0.7) }); }
      else { const dir = p.grip && p.grip < cx ? -1 : 1, hx = dir > 0 ? p.x0 : p.x1, [px, pz] = localOf(M, hx, p.zc); def = definePiece(nm, { kind: 'swing', pivot: [px, M.base, pz], ry: M.ry, parent, sgn: -dir, angle: 1.75 }); }
      p.def = def; parts.push(def);
      const [ax, az] = localOf(M, cx, front + 0.08);
      shared.inter.items.push({ type: drawer ? 'drawer' : 'cabinet', id: m.id, floor: M.floor, anchor: [ax, M.base + (M.y || 0) + (p.y0 + p.y1) / 2, az], range: 1.6, angle: 0.4, pieces: [def], text: () => t(def.target > 0.5 ? 'prompt.close' : 'prompt.open', { what: t('what.' + name) }), action: () => togglePiece(def) });
      def.item = shared.inter.items[shared.inter.items.length - 1];
    });
    calls.forEach((c, i) => {
      const p = owner.get(i); if (p === 'dup') return;
      cursor.group = p && p.def ? p.def.name : parent; api[c[0]](M, ...c[1]);
    });
    for (const p of panels) if (p.exterior.length) { cursor.group = p.def.name; for (const c of p.exterior) api[c[0]](M, ...c[1]); }
    cursor.group = parent;
  }
  Object.assign(K, { DOOR_ITEM, DRAWER_ITEM, LIGHT_TYPES, objectName, recordApi, buildItem, lightItem, curtainItem, furnitureItem });
}
